"""Detect a same-turn canned response template for the follow-up reminder."""

from __future__ import annotations

from typing import Optional

from rasa.core.constants import BOT_UTTERANCE_AGENT_MESSAGE_TYPE_KEY
from rasa.mantle.orchestration.turn_context import (
    FILLER_MESSAGE_TYPE,
    UTTER_ACTION_METADATA_KEY,
)
from rasa.shared.core.events import BotUttered, UserUttered
from rasa.shared.core.trackers import DialogueStateTracker


def canned_utter_delivered_this_turn(
    tracker: Optional[DialogueStateTracker],
) -> bool:
    """Returns whether a non-filler response template was delivered this turn."""
    if tracker is None:
        return False

    for event in reversed(tracker.events):
        if isinstance(event, UserUttered):
            return False
        if not isinstance(event, BotUttered) or not isinstance(event.metadata, dict):
            continue
        if (
            event.metadata.get(BOT_UTTERANCE_AGENT_MESSAGE_TYPE_KEY)
            == FILLER_MESSAGE_TYPE
        ):
            continue
        if event.metadata.get(UTTER_ACTION_METADATA_KEY):
            return True

    return False
